<script module lang="ts">
/**
 * The chat composer, where a prompt is written and sent (`design/components/prompt-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/prompt-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Icon,
  afterRender,
  agentFill,
  agentMember,
  composingKey,
  fitTextarea,
  focusAfterListRemoval,
  gateFiles,
  holdFieldEscape,
  joinSlot,
  promptPick,
  promptToken,
  watchEffect,
  type FileRejection,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/prompt-input.module.css'
import AttachmentChip from './AttachmentChip.svelte'
import Button from '../controls/Button.svelte'
import Skeleton from '../structure/Skeleton.svelte'
import type { AttachmentStatus } from './AttachmentChip.svelte'

export type PromptInputMaxRows = NonNullable<PromptInputProps['maxRows']>

export interface PromptAttachment {
  id: string
  name: string
  size?: number
  status?: AttachmentStatus
  message?: string
}

export interface PromptInputMessages {
  send: string
  stop: string
  attach: string
  remove: (name: string) => string
  uploading: (name: string) => string
  suggestions?: (count: number) => string
  loadingSuggestions?: string
  noSuggestions?: string
}

export interface PromptTriggerOption {
  id: string
  label: string
  description?: string
  icon?: IconRole
  insert?: string
}

export interface PromptTrigger {
  char: string
  label: string
  options: PromptTriggerOption[]
  at?: 'word' | 'start'
  filter?: 'contains' | 'startsWith' | false
  loading?: boolean
  onQueryChange?: (query: string) => void
  onSelect?: (option: PromptTriggerOption) => void
}

export interface PromptInputProps {
  /**
   * The native `accept` syntax (`.pdf`, `image/*`), also applied to drops and pastes.
   */
  accept?: string
  /**
   * The chips in the frame, always controlled by the app.
   */
  attachments?: PromptAttachment[]
  /**
   * Native passthrough, for a screen that has already moved the reader here.
   */
  autoFocus?: boolean
  defaultValue?: string
  disabled?: boolean
  /**
   * One line under the frame with the app's own note about what happens next.
   */
  hint?: string
  id?: string
  /**
   * The field's accessible name, needed because a composer has no visible label.
   */
  label: string
  /**
   * The toolbar's start slot for `sm` vocabulary controls, such as a model Select or a tools
   * Menu.
   */
  leading?: Snippet
  /**
   * How tall the field may grow before it scrolls, in lines.
   */
  maxRows?: 4 | 6 | 8 | 12
  /**
   * The maximum file size in bytes, above which a file never reaches `onAttach`.
   */
  maxSize?: number
  /**
   * All of the controls' text (generic English defaults), which localized hosts replace.
   */
  messages?: PromptInputMessages
  /**
   * When `false`, only one file is accepted at a time and the rest are rejected as `count`.
   */
  multiple?: boolean
  name?: string
  /**
   * Receives files that passed the gate (from the attach button, a drop or a paste) and shows
   * the attach button.
   */
  onAttach?: (files: File[]) => void
  onChange?: (value: string) => void
  /**
   * Receives the files the gate rejected with their reasons, which the app reports in its own
   * words.
   */
  onReject?: (rejections: FileRejection[]) => void
  onRemoveAttachment?: (id: string) => void
  /**
   * The stop button's handler while `streaming`.
   */
  onStop?: () => void
  /**
   * Called on Enter or the send button, and required because a composer that cannot send is a
   * Textarea.
   */
  onSubmit?: (value: string) => void
  placeholder?: string
  /**
   * Whether a reply is arriving, which turns send into stop and makes Enter do nothing.
   */
  streaming?: boolean
  /**
   * The toolbar's end, before the send control.
   */
  trailing?: Snippet
  /**
   * The characters that open a list of suggestions: `@` for people, `/` for commands.
   */
  triggers?: PromptTrigger[]
  value?: string
}
</script>

<script lang="ts">
let {
  accept,
  attachments = (() => [])(),
  autoFocus = false,
  defaultValue,
  disabled = false,
  hint,
  id: idOwn,
  label: labelOwn,
  leading,
  maxRows = 8,
  maxSize,
  messages = (() => ({
    send: 'Send',
    stop: 'Stop',
    attach: 'Attach',
    remove: (name) => `Remove ${name}`,
    uploading: (name) => `${name}: uploading`,
  }))(),
  multiple = true,
  name,
  onAttach,
  onChange,
  onReject,
  onRemoveAttachment,
  onStop,
  onSubmit,
  placeholder,
  streaming = false,
  trailing,
  triggers = (() => [])(),
  value,
}: PromptInputProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, name: name }))
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get attach() {
    return onAttach !== undefined
  },
  get change() {
    return onChange !== undefined
  },
  get reject() {
    return onReject !== undefined
  },
  get removeAttachment() {
    return onRemoveAttachment !== undefined
  },
  get stop() {
    return onStop !== undefined
  },
  get submit() {
    return onSubmit !== undefined
  },
}
// svelte-ignore state_referenced_locally
let uncontrolled = $state(defaultValue ?? '')
let dragover = $state(false)
let caret = $state(null as number | null)
let composing = $state(false)
let dismissed = $state(null as number | null)
let highlight = $state({ key: '', index: 0 })
let side = $state('top' as 'top' | 'bottom')
let reported = $state(null as string | null)
let pressed = $state(null as { id: string; at: number } | null)
let chips = $state<HTMLElement | null>(null)
let end = $state<HTMLElement | null>(null)
let field = $state<HTMLElement | null>(null)
let picker = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
let toolbar = $state<HTMLElement | null>(null)
const text = $derived(value ?? uncontrolled)
const empty = $derived(text.trim() === '' && attachments.length === 0)
const attachable = $derived(listening.attach && !disabled)
const setText = $derived((next: string) => ((uncontrolled = next), onChange?.(next)))
const submit = $derived(
  () =>
    !disabled &&
    !streaming &&
    !empty &&
    (onSubmit?.(text), value === undefined && (uncontrolled = '')),
)
const add = $derived(
  (list: FileList | File[] | null | undefined) =>
    attachable &&
    list != null &&
    list.length > 0 &&
    ((gate) => (
      gate.accepted.length > 0 && onAttach?.(gate.accepted),
      gate.rejected.length > 0 && onReject?.(gate.rejected)
    ))(gateFiles(Array.from(list), { accept, multiple, maxSize })),
)
const suggesting = $derived(triggers.length > 0)
const token = $derived(disabled ? null : promptToken(text, caret, triggers))
const trigger = $derived(token === null ? undefined : triggers[token.trigger])
const open = $derived(token !== null && trigger !== undefined && token.start !== dismissed)
const query = $derived(token?.query ?? '')
const collator = $derived(new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }))
const needle = $derived(query.normalize('NFC'))
const matches = $derived((label: string) =>
  ((candidate: string) =>
    needle === '' ||
    (trigger?.filter === 'startsWith'
      ? collator.compare(candidate.slice(0, needle.length), needle) === 0
      : Array.from({ length: Math.max(0, candidate.length - needle.length + 1) }, (_, at) =>
          candidate.slice(at, at + needle.length),
        ).some((part) => collator.compare(part, needle) === 0)))(label.normalize('NFC')),
)
const shown = $derived(
  !open || trigger === undefined
    ? []
    : trigger.filter === false
      ? trigger.options
      : trigger.options.filter((option) => matches(option.label)),
)
const loading = $derived(open && trigger?.loading === true)
const listKey = $derived(open && token !== null ? `${token.trigger}:${token.start}:${query}` : '')
const sideKey = $derived(open && token !== null ? `${token.trigger}:${token.start}` : null)
const active = $derived(
  shown.length === 0
    ? -1
    : highlight.key === listKey
      ? Math.min(highlight.index, shown.length - 1)
      : 0,
)
const listId = $derived(`${uid}-suggestions`)
const say = $derived({
  suggestions: messages.suggestions ?? ((count: number) => `${count} suggestions`),
  loadingSuggestions: messages.loadingSuggestions ?? 'Loading suggestions…',
  noSuggestions: messages.noSuggestions ?? 'No results',
})
const announcement = $derived(
  !open
    ? ''
    : loading
      ? say.loadingSuggestions
      : shown.length === 0
        ? say.noSuggestions
        : say.suggestions(shown.length),
)
const track = $derived((element: HTMLTextAreaElement, nextText: string) => {
  if (composing || element.value !== nextText) return
  const next =
    element.ownerDocument.activeElement === element &&
    element.selectionStart === element.selectionEnd
      ? element.selectionStart
      : null
  const found = disabled ? null : promptToken(nextText, next, triggers)
  const closed = found !== null && found.start === dismissed ? dismissed : null
  caret = next
  dismissed = closed
  const key =
    found === null || closed !== null ? null : found.trigger + ':' + found.start + ':' + found.query
  if (key === reported) return
  reported = key
  if (found !== null && key !== null) triggers[found.trigger]?.onQueryChange?.(found.query)
})
const pick = $derived((index: number) => {
  const option = shown[index]
  const at = token
  const by = trigger
  if (option === undefined || at === null || by === undefined || caret === null) return
  const next = promptPick(text, at, caret, option.insert ?? by.char + option.label)
  setText(next.text)
  caret = next.caret
  dismissed = null
  reported = null
  afterRender(() =>
    (field as HTMLTextAreaElement | null)?.setSelectionRange(next.caret, next.caret),
  )
  by.onSelect?.(option)
})
const listKeys = $derived((event: KeyboardEvent) => {
  const at = token
  if (!open || at === null) return false
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    if (shown.length === 0) return false
    event.preventDefault()
    highlight = {
      key: listKey,
      index:
        event.key === 'ArrowDown'
          ? Math.min(active + 1, shown.length - 1)
          : Math.max(active - 1, 0),
    }
    return true
  }
  if (event.key === 'Enter') {
    if (event.shiftKey || (active === -1 && !loading)) return false
    event.preventDefault()
    if (active !== -1) pick(active)
    return true
  }
  if (event.key === 'Tab') {
    if (event.shiftKey || active === -1) return false
    event.preventDefault()
    pick(active)
    return true
  }
  if (event.key === 'Escape') {
    // Escape closes the list and keeps the text. A dialog around the composer stays open,
    // because holdEscape has prevented the key's default.
    event.preventDefault()
    event.stopPropagation()
    dismissed = at.start
    reported = null
    return true
  }
  return false
})
const effect1 = () => {
  field && fitTextarea(field as HTMLTextAreaElement)
}
watchEffect(effect1, { watch: () => text })
const effect2 = () => {
  autoFocus &&
    field &&
    (field.focus(),
    (field as HTMLTextAreaElement).setSelectionRange(text.length, text.length),
    track(field as HTMLTextAreaElement, text))
}
watchEffect(effect2)
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = open && field ? holdFieldEscape(field) : () => {}
  release3 = () => {
    ran()
  }
}
watchEffect(effect3, { watch: () => open })
onDestroy(() => release3?.())
const effect4 = () => {
  pressed = focusAfterListRemoval(
    pressed,
    attachments.map((attachment) => attachment.id),
    (at) => chips?.children[at]?.querySelector<HTMLElement>('button'),
    field,
  )
}
watchEffect(effect4, { watch: () => attachments, mount: false })
const effect5 = () => {
  sideKey !== null &&
    root &&
    ((box: DOMRect) => (side = box.top >= window.innerHeight - box.bottom ? 'top' : 'bottom'))(
      (root as HTMLElement).getBoundingClientRect(),
    )
}
watchEffect(effect5, { watch: () => sideKey })
let release6: (() => void) | undefined
const effect6 = () => {
  release6?.()
  const ran = agentMember({
    member: 'PromptInput',
    element: () => field,
    state: () => ({
      value: text,
      attachments: attachments.map((attachment) => ({
        id: attachment.id,
        label: attachment.name,
        ...(listening.removeAttachment && !disabled ? {} : { disabled: true }),
      })),
      streaming: streaming,
      disabled: disabled,
    }),
    actions: {
      fill: { argument: 'text', run: (value) => agentFill(field, value) },
      clear: () => agentFill(field, ''),
      submit: () =>
        (() => {
          if (streaming) throw new Error('A reply is arriving; stop it before sending a prompt.')
          if (empty) throw new Error('The prompt is empty, and an empty prompt is not sent.')
          submit()
        })(),
      stop: () =>
        (() => {
          if (!streaming) throw new Error('No reply is arriving, so there is nothing to stop.')
          onStop?.()
        })(),
      remove: { argument: 'id', run: (value) => onRemoveAttachment?.(value) },
    },
    withholds: () => [
      chips,
      listening.attach ? toolbar?.firstElementChild : null,
      end?.lastElementChild,
    ],
  })
  release6 = () => {
    ran()
  }
}
watchEffect(effect6)
onDestroy(() => release6?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    data-state={streaming ? 'streaming' : dragover ? 'dragover' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-empty={(empty) ? '' : undefined}
    data-max-rows={String(maxRows)}
    data-member="prompt-input"
    ><div
      class={styles.frame}
      ondragover={(event) => { if (attachable) (event.preventDefault(), (dragover = true)) }}
      ondragleave={(event) => { if (!(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) (dragover = false) }}
      ondrop={(event) => { if (attachable) (event.preventDefault(), (dragover = false), add(event.dataTransfer?.files)) }}
      >{#if attachments.length > 0
        }<div bind:this={chips} class={styles.attachments}
          >{#each attachments as attachment (attachment.id)
            }{#if listening.removeAttachment && !disabled
              }<AttachmentChip
                name={attachment.name}
                size={attachment.size}
                status={attachment.status}
                message={attachment.message}
                removeLabel={messages.remove(attachment.name)}
                uploadingLabel={messages.uploading(attachment.name)}
                onRemove={() => { ((pressed = { id: attachment.id, at: attachments.indexOf(attachment) }), onRemoveAttachment?.(attachment.id)) }}
            />{:else
              }<AttachmentChip
                name={attachment.name}
                size={attachment.size}
                status={attachment.status}
                message={attachment.message}
                removeLabel={messages.remove(attachment.name)}
                uploadingLabel={messages.uploading(attachment.name)}
            />{/if
          }{/each
        }</div
      >{/if
      }<textarea
        bind:this={field}
        class={styles.field}
        {id}
        {name}
        rows={1}
        value={text}
        {placeholder}
        {disabled}
        aria-label={label}
        aria-autocomplete={(suggesting) ? 'list' : undefined}
        aria-haspopup={(suggesting) ? 'listbox' : undefined}
        aria-controls={(open) ? listId : undefined}
        aria-activedescendant={(open && active !== -1) ? `${uid}-suggestion-${active}` : undefined}
        oninput={(event) => { (setText((event.target as HTMLTextAreaElement).value), track(event.target as HTMLTextAreaElement, (event.target as HTMLTextAreaElement).value)) }}
        onkeydown={(event) => { if (!composingKey(event)) !listKeys(event) && event.key === 'Enter' && !event.shiftKey && (event.preventDefault(), submit()) }}
        onkeyup={(event) => { track(event.currentTarget as HTMLTextAreaElement, text) }}
        onpointerup={(event) => { track(event.currentTarget as HTMLTextAreaElement, text) }}
        onfocus={(event) => { track(event.currentTarget as HTMLTextAreaElement, text) }}
        onblur={() => { ((caret = null), (reported = null)) }}
        oncompositionstart={() => { (composing = true) }}
        oncompositionend={(event) => { ((composing = false), track(event.currentTarget as HTMLTextAreaElement, text)) }}
        onpaste={(event) => { if (attachable && (event.clipboardData?.files.length ?? 0) > 0) (event.preventDefault(), add(event.clipboardData?.files)) }}
      ></textarea
      ><div bind:this={toolbar} class={styles.toolbar}
        >{#if listening.attach
          }<Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="attach"
            label={messages.attach}
            {disabled}
            onClick={() => { picker?.click() }}
        />{/if
        }{@render leading?.()
        }<div bind:this={end} class={styles.end}
          >{@render trailing?.()
          }{#if streaming
            }<Button
              variant="outline"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="stop"
              label={messages.stop}
              onClick={() => { onStop?.() }}
          />{:else
            }<Button
              variant="solid"
              tone="accent"
              size="sm"
              iconOnly={true}
              icon="send"
              label={messages.send}
              disabled={disabled || empty}
              onClick={() => { submit() }}
          />{/if
        }</div
      ></div
      >{#if listening.attach
        }<input
          bind:this={picker}
          class={styles.picker}
          type="file"
          {accept}
          {multiple}
          {disabled}
          tabindex="-1"
          onchange={(event) => { (add((event.target as HTMLInputElement).files), ((event.target as HTMLInputElement).value = '')) }}
      />{/if
    }</div
    >{#if hint !== undefined}<p class={styles.hint}>{hint}</p>{/if
    }{#if open && trigger !== undefined
      }<div
        class={styles.suggestions}
        data-side={side}
        data-prompt-part="suggestions"
        onmousedown={(event) => { event.preventDefault() }}
        ><ul class={styles.listbox} id={listId} role="listbox" aria-label={trigger?.label}
          >{#each shown as option, index (option.id)
            }<li
              class={styles.option}
              id={`${uid}-suggestion-${index}`}
              role="option"
              aria-selected={index === active ? 'true' : 'false'}
              data-highlighted={(index === active) ? '' : undefined}
              onpointermove={() => { if (index !== active) (highlight = { key: listKey, index }) }}
              onclick={() => { pick(index) }}
              >{#if option.icon !== undefined
                }<span class={styles.glyph}><Icon name={option.icon} size="sm" /></span
              >{/if
              }<span class={styles.text}
                ><span class={styles.label}>{option.label}</span
                >{#if option.description !== undefined
                  }<span class={styles.description}>{option.description}</span
                >{/if
              }</span
            ></li
          >{/each
        }</ul
        >{#if loading
          }<div class={styles.rows} aria-hidden="true"
            >{#each [0, 1, 2] as row (row)
              }<div class={styles.row}><Skeleton textStep="sm" /></div
            >{/each
          }</div
        >{/if
        }{#if !loading && shown.length === 0
          }<div class={styles.empty} aria-hidden="true">{say.noSuggestions}</div
        >{/if
      }</div
    >{/if
    }{#if suggesting
      }<div class={styles.status} role="status" aria-live="polite">{announcement}</div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
